function loginUser(email, pass, callback) { setTimeout(() => callback(null, { id: 1, email }), 100); }
function getUserOrders(userId, callback) { setTimeout(() => callback(null, [{ id: 99, item: 'Book' }]), 100); }
function getTracking(orderId, callback) { setTimeout(() => callback(null, { status: 'Shipped' }), 100); }

// THE PYRAMID OF DOOM:
loginUser("test@test.com", "123", (error, user) => {
  if (error) return console.log(error);

  // Nest 1
  getUserOrders(user.id, (error, orders) => {
    if (error) return console.log(error);

    // Nest 2
    getTracking(orders[0].id, (error, tracking) => {
      if (error) return console.log(error);

      // Nest 3
      console.log("Finally! Tracking Status:", tracking.status);

    });
  });
});
